function roomEditMarkup(x){
 if(!x.location)return '';
 const fields={building:'건물',floor:'층',room:'병실 · 인실',bed:'침상(선택)'};
 return `<details><summary>병실 이동 · 수정</summary><form class="room-edit form" data-reference="${escapeHtml(x.reference)}">${Object.entries(fields).map(([key,label])=>`<label>${label}<input name="${key}" value="${escapeHtml(x.location[key]||'')}" maxlength="${key==='building'?40:key==='room'?30:20}" ${key==='bed'?'':'required'} ${key==='floor'?'pattern="[0-9]{1,2}층"':''}></label>`).join('')}<p>병실·인실 예: 803호 (1인실). 이동 후 침상도 확인해 주세요.</p><button type="submit" class="primary">변경 내용 저장</button><p class="edit-result" role="status"></p></form></details>`;
}
function bindRoomEditors(box,items){box.querySelectorAll('.room-edit').forEach(form=>{form.onsubmit=async e=>{e.preventDefault();if(!form.reportValidity())return;const item=items.find(x=>x.reference===form.dataset.reference),button=form.querySelector('button'),result=form.querySelector('.edit-result');button.disabled=true;try{const r=await fetch('/api/room-edit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reference:item.reference,expected:item.location,location:Object.fromEntries(new FormData(form))})});const data=await r.json();if(!r.ok)throw Error(data.error||'저장하지 못했습니다.');item.location=data.location;item.body=data.body;form.closest('article').querySelector('.message-body').textContent=data.body;result.textContent='저장 완료 · 상황판에도 변경된 병실이 표시됩니다.'}catch(error){result.textContent=error.message}finally{button.disabled=false}}})}
